// Spring Boot ya valida la pregunta; aquí se vuelve a validar porque el flujo no debe confiar en nadie
const b = $input.first().json.body || {};
const pregunta = String(b.pregunta ?? '').trim();
if (pregunta.length < 3 || pregunta.length > 500) {
  throw new Error('La pregunta debe tener entre 3 y 500 caracteres');
}
const umbral = Number(b.umbral);
if (!(umbral > 0 && umbral < 1)) {
  throw new Error('El umbral debe estar entre 0 y 1');
}
const maxFuentes = Math.min(Math.max(parseInt(b.max_fuentes ?? 5, 10) || 5, 1), 5);
// Spring Boot indica si el usuario aún tiene cupo diario de OpenAI (de pago); sin el dato, se permite
const permitirOpenai = b.permitir_openai !== false;
return [{ json: { consulta_id: b.consulta_id ?? null, pregunta, umbral, max_fuentes: maxFuentes, permitir_openai: permitirOpenai } }];

// Candidatos de pgvector ordenados por similitud (ya solo negocios activos). Se quedan los que superan el umbral.
const entrada = $('Validar entrada').first().json;
const candidatos = $input.all()
  .map((i) => i.json)
  .filter((c) => c.establecimiento_id != null)
  .map((c) => ({ establecimiento_id: Number(c.establecimiento_id), nombre: c.nombre, similitud: Number(c.similitud) }));
const fuentes = candidatos.filter((c) => c.similitud >= entrada.umbral);
return [{
  json: {
    fuentes,
    candidatos,
    mejor_similitud: candidatos.length ? candidatos[0].similitud : null,
    umbral: entrada.umbral,
  },
}];

const f = $input.first().json;
return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'Ningún negocio supera el umbral de similitud',
                  mejor_similitud: f.mejor_similitud, umbral: f.umbral, candidatos: f.candidatos } }];

// Solo las fichas que FastAPI devolvió (si un negocio se desactivó entre la búsqueda y este paso, ya no viene)
const fichas = $input.first().json.fichas || [];
const recuperadas = $('Filtrar por umbral').first().json.fuentes;
const ids = new Set(fichas.map((f) => f.id));
const fuentes = recuperadas.filter((f) => ids.has(f.establecimiento_id));
const pregunta = $('Validar entrada').first().json.pregunta;
const sistema = "Eres el asistente de Easy Search, una plataforma para encontrar negocios, productos y servicios en Bucaramanga y su área metropolitana (Colombia). Tu trabajo es entender de verdad lo que la persona necesita y orientarla con criterio entre los negocios registrados.\nRecibirás la pregunta de un usuario y las FICHAS de los negocios que la búsqueda semántica encontró como más relacionados.\n\nCómo razonar (antes de escribir):\n1. Identifica la NECESIDAD REAL detrás de la pregunta. Si describe un problema en lugar de nombrar un negocio (\"se me dañó la pantalla del celular\", \"me duele una muela\", \"se me pinchó una llanta\"), deduce qué tipo de negocio lo resuelve y busca ese tipo en las fichas.\n2. Detecta las condiciones que pidió: zona (barrio o municipio), presupuesto, horario (\"abierto ahora\", \"temprano\", \"domingo\"), producto concreto, para quién (niños, mascota, grupo) o preferencias.\n3. Revisa cada ficha y quédate SOLO con los negocios que sirven para esa necesidad según sus propios datos. Descarta los que no (un bar o un supermercado cuando pide una farmacia): no los menciones ni los incluyas en fuentes_usadas.\n4. Compara los que sirven y ordénalos con criterio: cuál conviene revisar primero y por qué, usando datos concretos de las fichas (productos o servicios de su carta, precios, horario, ubicación respecto a la zona pedida, calificación y reseñas si las hay).\n\nReglas OBLIGATORIAS:\n- Usa EXCLUSIVAMENTE la información de las fichas. No inventes negocios, productos, precios, horarios, direcciones, teléfonos, reseñas ni calificaciones.\n- NO deduzcas servicios ni especialidades a partir del NOMBRE de un negocio: usa solo los campos de su ficha.\n- UBICACIÓN: la ubicación de cada negocio es SOLO la del campo \"ubicacion\" de su ficha. Nunca digas que un negocio está en la zona que pidió el usuario si su ficha dice otra. Si pidió una zona y no hay opciones ahí, dilo claramente (ej. \"no encontré opciones en Cabecera; la más cercana registrada está en Piedecuesta\").\n- Si pidió un presupuesto u horario y la ficha no tiene ese dato, dilo con honestidad y sugiere confirmarlo con el negocio; si el dato existe y no cumple, no lo recomiendes como si cumpliera.\n- Si después de descartar no queda ningún negocio que sirva, o la pregunta no se puede responder con las fichas (recetas, información general, tareas, noticias, algo que ninguno ofrece), responde tiene_respuesta = false, deja pasos y fuentes_usadas vacíos y en respuesta explica en una o dos frases que no hay información suficiente en Easy Search (y, si ayuda, qué tipo de negocio buscar).\n- Si sí se puede responder: tiene_respuesta = true; respuesta = 3 a 5 frases en español, en segunda persona, que vayan al grano: la mejor opción primero con su razón concreta y, si hay más, en qué se diferencian; pasos = 2 a 4 pasos concretos y accionables (qué negocio revisar primero y por qué, qué producto o servicio preguntar, qué confirmar antes de ir); fuentes_usadas = ids de las fichas en las que te basaste.\n- Si una ficha tiene poca información, dilo con honestidad en lugar de rellenar.\n- Nombra los negocios solo por su nombre (y su barrio o municipio si ayuda a distinguirlos). NUNCA menciones ids, números de ficha ni la palabra \"ficha\": el usuario no los conoce.\n- Tono amable, cercano y directo, como alguien de la ciudad que conoce bien los negocios. Sin listas dentro de \"respuesta\".";
const usuario = JSON.stringify({ pregunta, fichas });
const esquema = {"type": "object", "properties": {"tiene_respuesta": {"type": "boolean"}, "respuesta": {"type": "string"}, "pasos": {"type": "array", "items": {"type": "string"}}, "fuentes_usadas": {"type": "array", "items": {"type": "integer"}}}, "required": ["tiene_respuesta", "respuesta", "pasos", "fuentes_usadas"]};

// Gemini (respaldo): API generateContent con salida JSON estructurada
const cuerpo = {
  systemInstruction: { parts: [{ text: sistema }] },
  contents: [{ role: 'user', parts: [{ text: usuario }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema: esquema, temperature: 0.2 },
};

// IA de pago (principal si hay clave): Grok (xAI) o OpenAI, ambos con la misma API Chat Completions y
// salida JSON estricta (obliga a respetar el formato). Grok va primero; LLM_PROVIDER puede forzar uno.
// Solo se mira SI existe cada clave, nunca su valor (las claves viven en la credencial "IA de pago").
const eleccion = ($env.LLM_PROVIDER || 'auto').toLowerCase();
const proveedor = ((eleccion === 'auto' || eleccion === 'xai') && $env.XAI_API_KEY) ? 'xai'
  : ((eleccion === 'auto' || eleccion === 'openai') && $env.OPENAI_API_KEY) ? 'openai' : null;
const modeloPago = proveedor === 'xai' ? ($env.XAI_MODEL || 'grok-4.7') : ($env.OPENAI_MODEL || 'gpt-4.1-mini');
// Grok: la API oficial o una pasarela compatible con OpenAI (XAI_BASE_URL)
const urlPago = proveedor === 'xai'
  ? ($env.XAI_BASE_URL || 'https://api.x.ai/v1').replace(/\/+$/, '') + '/chat/completions'
  : 'https://api.openai.com/v1/chat/completions';
// Modelos de razonamiento (Grok 4.x, serie "o", GPT-5): esfuerzo mínimo (rápido y barato) y margen en el tope
const razonamiento = /^(o\d|gpt-5)/i.test(modeloPago) || (/^grok/i.test(modeloPago) && !/non-reasoning/i.test(modeloPago));
const cuerpoPago = {
  model: modeloPago,
  messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }],
  response_format: { type: 'json_schema', json_schema: { name: 'respuesta_asistente', strict: true, schema: {"type": "object", "properties": {"tiene_respuesta": {"type": "boolean"}, "respuesta": {"type": "string"}, "pasos": {"type": "array", "items": {"type": "string"}}, "fuentes_usadas": {"type": "array", "items": {"type": "integer"}}}, "required": ["tiene_respuesta", "respuesta", "pasos", "fuentes_usadas"], "additionalProperties": false} } },
  // Tope de tokens de la respuesta (lo que más cuesta): lo normal son ~500
  max_completion_tokens: razonamiento ? 800 * 4 : 800,
  ...(razonamiento ? { reasoning_effort: /^gpt-5/i.test(modeloPago) ? 'minimal' : 'low' } : { temperature: 0.2 }),
};

// La IA de pago va primero salvo que no haya clave o el usuario haya agotado su cupo diario
// (lo decide Spring Boot); si no, responde Gemini (gratis)
const usarPago = proveedor !== null && $('Validar entrada').first().json.permitir_openai === true;
return [{ json: { fuentes, cuerpo: JSON.stringify(cuerpo), cuerpo_pago: JSON.stringify(cuerpoPago), url_pago: urlPago, usar_pago: usarPago } }];

// Respuesta de la IA que haya respondido: la de pago (Grok u OpenAI) o Gemini (principal o de respaldo)
const data = $input.first().json;
let r;
let modelo;
try {
  if (Array.isArray(data.choices)) {
    const mensaje = data.choices[0].message;
    if (mensaje.refusal) throw new Error('La IA de pago se negó a responder');
    r = JSON.parse(mensaje.content);
    modelo = data.model || 'ia-de-pago';
  } else {
    r = JSON.parse(data.candidates[0].content.parts[0].text);
    modelo = data.modelVersion || $env.GEMINI_MODEL;
  }
} catch (e) {
  throw new Error('La IA devolvió una respuesta que no es JSON válido');
}
const fuentes = $('Armar prompt').first().json.fuentes;
const recuperados = new Set(fuentes.map((f) => f.establecimiento_id));
// Solo cuentan como fuentes los ids que la búsqueda recuperó: si la IA cita otro id, se descarta
const usadas = (r.fuentes_usadas || []).map(Number).filter((id) => recuperados.has(id));
return [{
  json: {
    tiene_respuesta: r.tiene_respuesta === true && usadas.length > 0,
    respuesta: String(r.respuesta || '').trim(),
    pasos: (r.pasos || []).map((p) => String(p).trim()).filter(Boolean).slice(0, 6),
    ids: usadas,
    modelo,
  },
}];

const f = $('Filtrar por umbral').first().json;
return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'Las fuentes encontradas no responden la pregunta',
                  explicacion: $input.first().json.respuesta, mejor_similitud: f.mejor_similitud, umbral: f.umbral } }];

// Resultado final para Spring Boot
const validado = $input.first().json;               // respuesta y pasos ya sin datos inventados
const ia = $('Leer respuesta de la IA').first().json;
const filtro = $('Filtrar por umbral').first().json;
const porId = new Map($('Armar prompt').first().json.fuentes.map((f) => [f.establecimiento_id, f]));
const fuentes = ia.ids.map((id) => porId.get(id)).filter(Boolean);
if ((validado.respuesta || '').length < 15) {
  // La validación eliminó casi todo: era información sin respaldo en las fichas
  return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'La respuesta generada no tenía respaldo en los datos',
                    mejor_similitud: filtro.mejor_similitud, umbral: filtro.umbral } }];
}
return [{
  json: {
    estado: 'RESPONDIDA',
    respuesta: validado.respuesta,
    pasos: validado.pasos,
    fuentes,
    mejor_similitud: filtro.mejor_similitud,
    umbral: filtro.umbral,
    modelo: ia.modelo,
    frases_eliminadas: validado.frases_eliminadas === true,
  },
}];

// Llega aquí cuando falla un paso (salida de error de los nodos HTTP y Postgres)
const mensajes = {
  'Vector de la pregunta (e5)': 'El servicio de embeddings no respondió',
  'Buscar en pgvector': 'La búsqueda en pgvector falló',
  'Fichas de las fuentes': 'No se pudieron leer las fichas de los negocios',
  'Gemini (respaldo)': 'Ninguna IA respondió (la de pago, Gemini y su modelo de respaldo)',
  'Validar contra las fichas': 'No se pudo validar la respuesta contra los datos',
};
const paso = $prevNode.name;
const tecnico = String($input.first().json.error?.message || $input.first().json.error || '').slice(0, 200);
return [{ json: { estado: 'ERROR', detalle: mensajes[paso] || `Falló el paso ${paso}`, paso, tecnico } }];
